customCss:
/* ===== Garden Kitchen ===== */

:root {
  --garden-leaf: #24361e;
  --garden-card: #3b5a40;
  --garden-sage: #a7bd84;
  --garden-sage-hi: #bfd29c;
  --garden-mint: #8fc3a0;
  --garden-cream: #ebe7c6;
  --garden-ink: #22381f;
  --garden-pink: #e2557a;
}

/* background.webp is one painting that runs behind the sidebar, top bar and page alike
   (the sunny garden with daisies, tulips and the Fresh Ingredients sign across the top; deep leaf
   green behind the sidebar with the Good Food Good Mood sign and watering can at its foot; a
   soft cream wash over the garden under the recipes). Nothing here draws a hard edge. */

/* The page sits on light cream, so page text is dark leaf ink in both light and dark mode; the
   recipe cards, sidebar and top bar are dark green or sit on the garden, so their text stays light. */
.v-application .v-main {
  --v-theme-on-surface: 34, 56, 31;
  --v-theme-on-background: 34, 56, 31;
  color: rgb(34, 56, 31);
}
.v-application .v-main .v-card,
.v-application .v-navigation-drawer,
.v-application .v-app-bar.v-toolbar,
.v-overlay__content {
  --v-theme-on-surface: 255, 255, 250;
  --v-theme-on-background: 255, 255, 250;
}
.v-application .v-navigation-drawer {
  background-color: rgba(26, 44, 24, 0.55) !important;
  border-right: 1px solid rgba(255, 255, 255, 0.12) !important;
}
.v-application .v-app-bar.v-toolbar {
  background-color: rgba(26, 44, 24, 0.12) !important;
  border-bottom: none !important;
  box-shadow: none !important;
}

/* Keep the scene sharp behind the sidebar and top bar */
.v-application .v-navigation-drawer, .v-application .v-app-bar.v-toolbar { backdrop-filter: none !important; }

/* Logo: bold white wordmark */
.v-app-bar .v-toolbar-title__placeholder {
  font-weight: 700;
  font-size: 1.6rem;
  color: #ffffff;
  text-shadow: 0 2px 6px rgba(20, 40, 18, 0.85);
  overflow: visible;
}
.v-app-bar .v-icon,
.v-app-bar .v-btn,
.v-app-bar svg { color: #ffffff !important; filter: drop-shadow(0 1px 3px rgba(20, 40, 18, 0.9)); }

/* Sentence-case buttons ("Logout", "Random", "Create") */
.v-application .v-btn { text-transform: none; letter-spacing: 0.1px; }

/* Top bar search ("Press '/'"): leaf-green pill with a light rim */
.v-app-bar .v-field.bg-primary-darken-1 {
  background: rgba(36, 60, 32, 0.85) !important;
  border: 1.5px solid rgba(220, 235, 200, 0.7);
  border-radius: 22px !important;
  color: #f2f6e8 !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.35);
}
.v-app-bar .v-field.bg-primary-darken-1 input::placeholder { color: #e6eed6; opacity: 1; }

/* ---------- Sidebar contents ---------- */
.v-navigation-drawer .v-list-item-title,
.v-navigation-drawer .v-list-item__content {
  color: #ffffff;
  font-weight: 500;
  text-shadow: 0 1px 3px rgba(10, 20, 8, 0.9);
}
.v-navigation-drawer .v-list-item .v-icon { color: #ffffff; opacity: 1; }
.v-navigation-drawer .v-list-item-subtitle { color: #eef3e2; opacity: 0.95; }
.v-navigation-drawer .v-list-item { border-radius: 6px; }
.v-navigation-drawer .v-list-item:hover > .v-list-item__overlay { background: var(--garden-sage); opacity: 0.2; }

/* Active item: sage leaf bar */
.v-navigation-drawer .v-list-item--active {
  background: linear-gradient(90deg, #9db57a, #b5c98f) !important;
  border-radius: 6px !important;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.35);
}
.v-navigation-drawer .v-list-item--active .v-list-item__overlay { opacity: 0 !important; }
.v-navigation-drawer .v-list-item--active .v-list-item-title,
.v-navigation-drawer .v-list-item--active .v-list-item__content,
.v-navigation-drawer .v-list-item--active .v-icon { color: var(--garden-ink) !important; text-shadow: none; }

/* Create button: fresh green pill */
.v-navigation-drawer .v-btn.bg-primary,
.v-navigation-drawer .v-btn--variant-elevated {
  background: linear-gradient(180deg, #5cb062, #3f8a45) !important;
  color: #ffffff !important;
  border-radius: 999px !important;
  font-weight: 600;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.25) !important;
}

.v-navigation-drawer .v-divider { border-color: rgba(255, 255, 255, 0.18) !important; opacity: 1; }

/* ---------- Page ---------- */

/* Page headings: condensed leaf-green ("Recipes", page titles) */
.v-main .text-headline-small {
  font-family: "Fira Sans Condensed", "Fira Sans", sans-serif !important;
  font-size: 1.9rem !important;
  font-weight: 600 !important;
}
.v-main h1, .v-main h2, .v-main .text-h3, .v-main .text-h4, .v-main .text-h5, .v-main .text-headline-small {
  color: var(--garden-ink);
  text-shadow: 0 1px 0 rgba(255, 255, 240, 0.8);
}

/* Search field: pale sage with a leaf-green rim */
.v-main .v-field--variant-outlined,
.v-main .v-field--variant-solo,
.v-main .v-field--variant-filled {
  background: rgba(240, 242, 214, 0.95) !important;
  border-radius: 6px !important;
  box-shadow: 0 0 0 2px #3b5a40, 0 3px 10px rgba(0, 0, 0, 0.25);
  color: var(--garden-ink);
}
.v-main .v-field--variant-outlined .v-field__outline { color: #6e8f5a; --v-field-border-opacity: 1; }
.v-main .v-field--focused .v-field__outline { color: #3f8a45 !important; }
.v-main .v-field input::placeholder { color: #4c6444; opacity: 1; }

/* Filter + sort buttons: sage pills with dark leaf text */
.v-main .v-btn.bg-accent,
.v-main .v-btn.bg-secondary,
.v-main .v-btn.bg-primary {
  background: linear-gradient(180deg, #bfd29c, #9db57a) !important;
  color: var(--garden-ink) !important;
  border: 1.5px solid #3b5a40;
  border-radius: 8px !important;
  font-weight: 600;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.4) !important;
}
.v-main .v-btn.bg-accent:hover,
.v-main .v-btn.bg-secondary:hover,
.v-main .v-btn.bg-primary:hover { background: linear-gradient(180deg, #cde0ac, #abc387) !important; }

/* Recipe cards: deep leaf green */
.v-main .v-card {
  background-color: #3b5a40 !important;
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  border-radius: 6px !important;
  box-shadow: 0 6px 14px rgba(30, 50, 25, 0.35) !important;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.v-main .v-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 22px rgba(30, 50, 25, 0.45), 0 0 0 2px rgba(191, 210, 156, 0.8) !important;
}

/* Recipe titles: white */
.v-main .v-card .v-card-title,
.v-main .v-card .v-card-title * {
  font-weight: 500 !important;
  font-size: 1.08rem;
  color: #ffffff;
}

/* Tags: mint pills with dark leaf text */
.v-main .v-card .v-chip {
  background: #9fd0ae !important;
  color: var(--garden-ink) !important;
  border-radius: 6px !important;
  font-weight: 600;
  font-size: 0.74rem;
}
.v-main .v-card .v-chip .v-chip__overlay { opacity: 0 !important; }

/* Heart, stars and card menu: soft cream */
.v-main .v-card .v-rating .v-btn,
.v-main .v-card .v-rating .v-icon,
.v-main .v-card .v-card-actions .v-btn { color: #f2eed2 !important; }

/* ---------- Menus and dialogs: leaf green with light text ---------- */
.v-overlay__content > .v-list,
.v-overlay__content > .v-card,
.v-menu > .v-overlay__content > .v-list {
  background: #2f4a33 !important;
  color: #ffffff !important;
  border: 1px solid rgba(191, 210, 156, 0.5);
  border-radius: 8px !important;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.45) !important;
}

/* Accessible focus ring */
.v-btn:focus-visible,
.v-list-item:focus-visible,
.v-chip:focus-visible { outline: 2px solid #e2557a; outline-offset: 2px; }

/* Scrollbar */
html { scrollbar-color: #6e8f5a #ebe7c6; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: #ebe7c6; }
::-webkit-scrollbar-thumb { background: #6e8f5a; border-radius: 6px; border: 2px solid #ebe7c6; }

@media (prefers-reduced-motion: reduce) {
  .v-main .v-card, .v-main .v-card:hover { transition: none; transform: none; }
}

/* Top bar: fully see-through, with no blur. Mealie tints and blurs the bar (panelOpacity), which
   showed as a hazy band across the top of the painting; the painting itself gives the bar its look.
   The repeated classes raise specificity above Mealie's own rules, and the bar's inner layers and
   pseudo-elements are cleared too, wherever the tint or blur is applied. */
html:root body .v-application header.v-app-bar.v-app-bar.v-toolbar.v-toolbar,
html:root body .v-application .v-app-bar.v-app-bar.v-toolbar.v-toolbar,
html:root body .v-application .v-app-bar.v-app-bar.v-toolbar::before,
html:root body .v-application .v-app-bar.v-app-bar.v-toolbar::after,
html:root body .v-application .v-app-bar.v-app-bar .v-toolbar__content,
html:root body .v-application .v-app-bar.v-app-bar .v-toolbar__content::before,
html:root body .v-application .v-app-bar.v-app-bar .v-toolbar__content::after,
html:root body .v-application .v-app-bar.v-app-bar .v-toolbar__image,
html:root body .v-application .v-app-bar.v-app-bar .v-toolbar__extension {
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  filter: none !important;
  box-shadow: none !important;
}
